<?php require_once __DIR__.'/../../libs/board-games.inc.php';if(!bg_ready()): ?><p>Il registro dei giochi è in preparazione.</p><?php else:$gameHistory=bg_history((int)$sheet['rpg_id'],max(1,min(10000,(int)($_GET['games_page']??1)))); ?>
<header><span class="rpg-eyebrow">Il tavolo delle strategie</span><h2>Giochi</h2><p>Scacchi e Dama italiana · Le partite sono indipendenti dalle azioni narrative.</p></header>
<div class="bg-stats-grid"><?php foreach(['scacchi'=>'Scacchi','dama'=>'Dama italiana'] as $key=>$label):$rating=array_values(array_filter($gameHistory['ratings'],static fn($r)=>$r['game_key']===$key))[0]??['elo'=>1200,'wins'=>0,'losses'=>0,'draws'=>0,'games'=>0,'intelligence'=>0]; ?><section class="bg-stats-card"><h3><?=$label?></h3><strong><?=(int)$rating['elo']?> ELO</strong><p><?=(int)$rating['wins']?> vittorie · <?=(int)$rating['losses']?> sconfitte · <?=(int)$rating['draws']?> patte</p><p><?=(int)$rating['games']?> partite · <strong>+<?=(int)$rating['intelligence']?> Intelligenza</strong></p></section><?php endforeach; ?></div>
<h3>Il registro degli incontri</h3><div class="bg-history-list"><?php foreach($gameHistory['matches'] as $m):$result=rpg_decode($m['result_json']);$opponent=(int)$m['a']===(int)$sheet['rpg_id']?$m['name_b']:$m['name_a']; ?><article class="bg-history-row"><span><a href="/chat/index.php?chat=<?=rawurlencode($m['chat_key'])?>&amp;board_game=<?=(int)$m['id']?>"><strong><?=$h($opponent)?></strong></a><small> · <?=$m['game_key']==='dama'?'Dama italiana':'Scacchi'?> · <?=date('d/m/Y H:i',(int)$m['finished_at'])?></small><p><?=$h($m['reason'])?><?=!empty($result['computer'])?' · Allenamento PNG · Nessun premio o ELO':''?></p></span><span><strong><?=!empty($result['void'])?'Annullata':((int)$m['winner']===0?'Patta':((int)$m['winner']===(int)$sheet['rpg_id']?'Vittoria':'Sconfitta'))?></strong><p><?=(int)($result['plies']??0)?> mosse · <?=(int)($result['duration']??0)?> secondi · +<?=(int)($result['intelligence'][$sheet['rpg_id']]??0)?> INT</p></span></article><?php endforeach;if(!$gameHistory['matches']): ?><p>Nessuna partita conclusa.</p><?php endif; ?></div><nav class="bg-actions"><?php if($gameHistory['page']>1): ?><a href="?Id=<?=(int)$sheet['rpg_id']?>&amp;games_page=<?=$gameHistory['page']-1?>#giochi">Incontri precedenti</a><?php endif;if($gameHistory['more']): ?><a href="?Id=<?=(int)$sheet['rpg_id']?>&amp;games_page=<?=$gameHistory['page']+1?>#giochi">Incontri più lontani</a><?php endif; ?></nav><?php endif; ?>
